/**
 * Generated by `npm run arena:rulesets` from `src/lib/arena/rulesets/dbs/*.rules`.
 * Do not edit: edit the `.rules` file and run the script again.
 *
 * The text lives here so the loader can be pure — see the script's header.
 */
export const FILES: Record<string, string> = {
  "attributes.rules": "-- What a card and a player have, as declarations.\n--\n-- Sections are `docs/rules/rulemanual.txt`: §2 is the parts of a card, §1-2\n-- energy costs (total and specified), §1-9 the front and back sides, §1-14\n-- energy markers, §9-9-1 the order continuous effects are applied in, §20-1\n-- names a skill gives a card in all areas and §20-21 increasing or reducing\n-- an energy cost.\n--\n-- `printed: true` means the value is read off the card itself — \"the\n-- information specified on a card itself\", which §9-9-1-1 makes the base\n-- reference for everything below it. `layers:` is the order the game then\n-- applies to reach the value the rules actually use, §9-9-1 throughout:\n--   printed   the face value (9-9-1-1)\n--   rewrite   every continuous effect except those that rewrite a number\n--             (9-9-1-2)\n--   numeric   the continuous effects that rewrite a number (9-9-1-3)\n-- A cost has its own two layers because a reduction is not a rewrite of the\n-- printed cost but a discount on the price being paid (20-21): `reduction`\n-- is the flat one, `specified` the coloured one, and they move apart —\n-- `docs/arena-history-lessons.md`, 8 Sep 2026 and the owner's BT19-039\n-- ruling of 9 Sep 2026.\n--\n-- Where an attribute's real domain cannot be said in this grammar — `value:`\n-- knows five shapes and no enum, no union and no map — the text says what the\n-- domain is instead, and the history entry of 12 Sep 2026 records the gap\n-- rather than the file stretching to cover it.\n\n-- ── printed on the card (§2) ───────────────────────────────────────────────\n\nDEFINE ATTRIBUTE id                                                       -- §2-14\n  of: card\n  value: string\n  printed: true\n  text: \"the card number, which is what a copy limit and every reference to a card counts by (2-14, 6-1-5-1)\"\n\nDEFINE ATTRIBUTE name                                                     -- §2-3\n  of: card\n  value: string\n  printed: true\n  text: \"the card name (2-3)\"\n\nDEFINE ATTRIBUTE type                                                     -- §2-1\n  of: card\n  value: string\n  printed: true\n  text: \"the card type, one of LEADER, BATTLE, EXTRA, UNISON, Z-LEADER, Z-BATTLE, Z-EXTRA, Z-UNISON and TOKEN (2-1, 10 to 19)\"\n\nDEFINE ATTRIBUTE colors                                                   -- §2-2\n  of: card\n  value: colors\n  printed: true\n  text: \"the card's colors: red, blue, green, yellow, black, white, or none of them (1-8, 2-2)\"\n\nDEFINE ATTRIBUTE energyCost                                               -- §2-5\n  of: card\n  value: number\n  printed: true\n  text: \"the total cost of playing the card from hand; an X cost is a number its master chooses when it is paid and zero at every other time (1-2-2, 1-2-2-2)\"\n\nDEFINE ATTRIBUTE specifiedCost                                            -- §1-2-3\n  of: card\n  value: colors\n  printed: true\n  text: \"the coloured orbs of the energy cost, one entry per orb, that must be matched in colour when the cost is paid (1-2-3, 5-3)\"\n\nDEFINE ATTRIBUTE zEnergyCost                                             -- §2-6\n  of: card\n  value: number\n  printed: true\n  text: \"the Z-Energy cost of playing the card from the Z-Deck (1-4, 2-6)\"\n\nDEFINE ATTRIBUTE power                                                    -- §2-7\n  of: card\n  value: number\n  printed: true\n  layers: [printed, rewrite, numeric]\n  text: \"the number a battle is decided by (2-7, 8-4); combo power is added to it only in the Damage Step (5-7)\"\n\nDEFINE ATTRIBUTE comboCost                                                -- §2-9\n  of: card\n  value: number\n  printed: true\n  text: \"the energy paid to use the card in a combo (2-9, 5-6)\"\n\nDEFINE ATTRIBUTE comboPower                                               -- §2-8\n  of: card\n  value: number\n  printed: true\n  layers: [printed, rewrite, numeric]\n  text: \"the power the card adds when it is used in a combo (2-8, 5-7)\"\n\nDEFINE ATTRIBUTE characters                                               -- §2-10\n  of: card\n  value: strings\n  printed: true\n  text: \"the character names the card carries, written in angle brackets (2-10)\"\n\nDEFINE ATTRIBUTE traits                                                   -- §2-11\n  of: card\n  value: strings\n  printed: true\n  text: \"the special traits the card carries, written in double angle brackets (2-11)\"\n\nDEFINE ATTRIBUTE skill                                                    -- §2-4\n  of: card\n  value: string\n  printed: true\n  text: \"the card's text box, which is every skill it has before any is gained or negated (2-4, 1-5)\"\n\nDEFINE ATTRIBUTE back                                                     -- §1-9\n  of: card\n  value: boolean\n  printed: true\n  text: \"whether the card has a back side to turn to — a Leader's awakened face, or a Z-Leader's single face (1-9). What is printed on that face is a face of its own, which this grammar has no kind for; see the history entry of 12 Sep 2026\"\n\nDEFINE ATTRIBUTE alsoNames                                                -- §20-1\n  of: card\n  value: strings\n  printed: false\n  text: \"the card names a skill gave this card in all areas; it answers to these as well as to its printed name, never instead of it (20-1)\"\n\n-- ── what the board makes of them (§9-9-1, §20-21) ──────────────────────────\n\nDEFINE ATTRIBUTE costOf                                                   -- §20-21\n  of: card\n  value: number\n  printed: false\n  layers: [printed, reduction, specified]\n  text: \"the price of playing this card as it stands: the printed total cost, less every cost reduction in force, with the coloured half relaxed or tightened on its own (20-21-1, 20-21-2)\"\n\nDEFINE ATTRIBUTE comboCostOf                                              -- §20-21\n  of: card\n  value: number\n  printed: false\n  layers: [printed, reduction]\n  text: \"the combo cost as it stands, after every reducer in force, and never less than zero (5-7-3, 20-21-2)\"\n\nDEFINE ATTRIBUTE zEnergyCostOf                                            -- §20-21\n  of: card\n  value: number\n  printed: false\n  layers: [printed, reduction]\n  text: \"the Z-Energy cost as it stands, after every reducer in force, and never less than zero (5-4, 20-21-2)\"\n\n-- ── what a player has (§1-14) ──────────────────────────────────────────────\n\nDEFINE ATTRIBUTE energyMarkers                                            -- §1-14\n  of: player\n  value: number\n  printed: false\n  text: \"the energy markers in a player's Energy Area: each pays one energy of the Leader's colour, and neither is a card nor is energy (1-14-1, 1-14-2, 1-14-3)\"\n",
  "game.rules": "-- The Dragon Ball Super Card Game itself: how a player starts, what a turn is\n-- made of, and how the game ends.\n--\n-- Sections are `docs/rules/rulemanual.txt`: §0-1-3 ending the game, §6-1 the\n-- Leader Card and the decks, §6-2 pre-game preparations, §7-1 the turn,\n-- §7-2 the Charge Phase, §7-3 the Main Phase, §7-4 the End Phase.\n--\n-- Three things the manual says here that the grammar has no field for are\n-- left out rather than written wrongly, and each is recorded in the history\n-- entry of 12 Sep 2026:\n--   * the deck is 50 **to 60** cards (6-1-3) and a Z-Deck is **up to** 10\n--     (6-1-4) — `deck:` and `zDeck:` are one number each, so they are read\n--     below as the deck's minimum and the Z-Deck's maximum;\n--   * a deck may hold up to 4 copies of a card number (6-1-5-1) — there is no\n--     field for a copy limit;\n--   * only the player who goes **second** places an energy marker (6-2-1-11)\n--     — `startMarkers:` is one number for both players, so it is left out and\n--     the setup step below is where that rule is said.\n\nDEFINE GAME dbs                                                           -- §6-1\n  title: \"Dragon Ball Super Card Game\"\n  players: 2\n  deck: 50\n  zDeck: 10\n  hand: 6\n  life: 8\n  mulligan: true\n  firstPlayerDraws: false\n  phases: [charge, main, mainEnd, end]\n\n-- ── the phases ────────────────────────────────────────────────────────────\n--\n-- A turn is three phases, each made of steps, and a phase or a step exists\n-- even when nothing happens in it (7-1-1). `setup` and `over` are not phases\n-- of a turn: they are the pre-game procedure (6-2) and the end of the game\n-- (0-1-3), which this engine runs as phases of their own and which is why\n-- `DEFINE GAME`'s `phases:` above lists four names and not six.\n--\n-- The manual makes the Main Phase End Step a step of the Main Phase\n-- (7-3-5); this engine has run it as a phase of its own since before the\n-- rules language existed, so it is declared as one here. The history entry of\n-- 12 Sep 2026 records the difference.\n--\n-- `actions:` is left off every phase: the moves a player may declare (7-3-4)\n-- are `DEFINE ACTION`s, and the loader refuses a phase naming one that\n-- nothing declares. They arrive with `play.rules`.\n\nDEFINE PHASE setup                                                        -- §6-2\n  steps: [setupPresent, setupLeader, setupLeaderPending, setupFirstPlayer, setupShuffle, setupZDeck, setupHand, setupMulligan, setupLife, setupEnergyMarker, setupStart]\n  auto: false\n  text: \"the pre-game procedure, before the first turn: leaders down, first player chosen, hands drawn and life set out (6-2-1)\"\n\nDEFINE PHASE charge                                                       -- §7-2\n  steps: [chargeTurnEffects, chargeContinuousEnd, chargePending, chargeActivate, chargeDraw, chargeEnergy]\n  auto: false\n  text: \"the rules processing at the start of a turn, with a checkpoint after each step (7-2-1, 7-2-6, 7-2-8, 7-2-10, 7-2-12)\"\n\nDEFINE PHASE main                                                         -- §7-3\n  steps: [mainPending, mainActions]\n  auto: false\n  text: \"the phase the turn player takes their moves in, returning to a checkpoint after each one (7-3-1, 7-3-4)\"\n\nDEFINE PHASE mainEnd                                                      -- §7-3-5\n  steps: [mainEndPending, mainEndEffects]\n  auto: true\n  text: \"the Main Phase End Step, which the manual counts as a step of the Main Phase and this engine runs as a phase (7-3-5)\"\n\nDEFINE PHASE end                                                          -- §7-4\n  steps: [endPending, endRepeat, endEffects, endTurn]\n  auto: true\n  text: \"the end of the turn: what answers to it is made pending, what lasted for the turn ends, and the other player becomes the turn player (7-4-1, 7-4-7)\"\n\nDEFINE PHASE over                                                         -- §0-1-3\n  steps: [gameEnd]\n  auto: true\n  text: \"the game is over, which is not a phase of a turn: a player has lost and nothing further is played (0-1-3)\"\n\n-- ── setup (§6-2-1) ────────────────────────────────────────────────────────\n\nDEFINE STEP setupPresent                                                  -- §6-2-1-1\n  phase: \"setup\"\n  optional: false\n  text: \"each player presents the Leader Card, deck and Z-Deck they will use, which must meet the deck construction rules (6-2-1-1, 6-1)\"\n\nDEFINE STEP setupLeader                                                   -- §6-2-1-2\n  phase: \"setup\"\n  optional: false\n  text: \"each player places their Leader Card front side up in their Leader Area (6-2-1-2)\"\n\nDEFINE STEP setupLeaderPending                                            -- §6-2-1-3\n  phase: \"setup\"\n  optional: false\n  text: \"trigger conditions for \\\"when this card is placed in a Leader Area\\\" skills enter pending (6-2-1-3)\"\n\nDEFINE STEP setupFirstPlayer                                              -- §6-2-1-4\n  phase: \"setup\"\n  optional: false\n  prompt: \"chooseFirst\"\n  text: \"by a random method one player is chosen, and that player chooses who goes first (6-2-1-4, 6-2-1-5)\"\n\nDEFINE STEP setupShuffle                                                  -- §6-2-1-7\n  phase: \"setup\"\n  optional: false\n  text: \"each player shuffles their deck and places it face down in their Deck Area (6-2-1-7)\"\n\nDEFINE STEP setupZDeck                                                    -- §6-2-1-8\n  phase: \"setup\"\n  optional: false\n  text: \"each player places their Z-Deck face down in their Z-Deck Area (6-2-1-8)\"\n\nDEFINE STEP setupHand                                                     -- §6-2-1-9\n  phase: \"setup\"\n  optional: false\n  text: \"each player draws 6 cards from their deck as their opening hand (6-2-1-9)\"\n\nDEFINE STEP setupMulligan                                                 -- §6-2-1-9-1\n  phase: \"setup\"\n  optional: true\n  prompt: \"mulligan\"\n  text: \"beginning with the starting player, each player may return their hand to their deck, shuffle, and draw 6 new cards — once (6-2-1-9, 6-2-1-9-1)\"\n\nDEFINE STEP setupLife                                                     -- §6-2-1-10\n  phase: \"setup\"\n  optional: false\n  text: \"each player places the top 8 cards of their deck face down in their Life Area (6-2-1-10)\"\n\nDEFINE STEP setupEnergyMarker                                             -- §6-2-1-11\n  phase: \"setup\"\n  optional: false\n  text: \"the player who goes second places 1 energy marker in their Energy Area, and the player who goes first places none (6-2-1-11)\"\n\nDEFINE STEP setupStart                                                    -- §6-2-1-12\n  phase: \"setup\"\n  optional: false\n  text: \"the first player begins the game and starts their turn (6-2-1-12)\"\n\n-- ── the Charge Phase (§7-2) ───────────────────────────────────────────────\n\nDEFINE STEP chargeTurnEffects                                             -- §7-2-2\n  phase: \"charge\"\n  optional: false\n  text: \"effects that last \\\"for the turn\\\" occur, for the turn player and then for the non-turn player (7-2-2, 7-2-3)\"\n\nDEFINE STEP chargeContinuousEnd                                           -- §7-2-4\n  phase: \"charge\"\n  optional: false\n  text: \"continuous effects that last \\\"until the start of your opponent's turn\\\" end (7-2-4)\"\n\nDEFINE STEP chargePending                                                 -- §7-2-5\n  phase: \"charge\"\n  optional: false\n  text: \"effects that read \\\"at the beginning of the turn\\\" and \\\"at the beginning of the Charge Phase\\\" enter pending (7-2-5)\"\n\nDEFINE STEP chargeActivate                                                -- §7-2-7\n  phase: \"charge\"\n  optional: false\n  text: \"each player switches every card in their Leader, Battle, Energy and Unison Areas that is in Rest Mode to Active Mode (7-2-7)\"\n\nDEFINE STEP chargeDraw                                                    -- §7-2-9\n  phase: \"charge\"\n  optional: false\n  text: \"the turn player draws 1 card, except the player who goes first, on their first turn (7-2-9, 7-2-9-1)\"\n\nDEFINE STEP chargeEnergy                                                  -- §7-2-11\n  phase: \"charge\"\n  optional: true\n  prompt: \"charge\"\n  text: \"the turn player may place 1 card from their hand in their Energy Area (7-2-11)\"\n\n-- ── the Main Phase (§7-3) ─────────────────────────────────────────────────\n\nDEFINE STEP mainPending                                                   -- §7-3-2\n  phase: \"main\"\n  optional: false\n  text: \"effects that read \\\"at the beginning of the Main Phase\\\" enter pending (7-3-2)\"\n\nDEFINE STEP mainActions                                                   -- §7-3-4\n  phase: \"main\"\n  optional: false\n  prompt: \"main\"\n  text: \"the turn player is granted a free timing: play a card, activate an [Activate : Main] skill, grow a Unison Card, attack, or end the Main Phase (7-3-4)\"\n\nDEFINE STEP mainEndPending                                                -- §7-3-5-1-1\n  phase: \"mainEnd\"\n  optional: false\n  text: \"skills that read \\\"at the end of the Main Phase\\\" enter pending (7-3-5-1-1)\"\n\nDEFINE STEP mainEndEffects                                                -- §7-3-5-1-3\n  phase: \"mainEnd\"\n  optional: false\n  text: \"effects that last \\\"for the Main Phase\\\" end, for the turn player and then for the non-turn player (7-3-5-1-3, 7-3-5-1-4)\"\n\n-- ── the End Phase (§7-4) ──────────────────────────────────────────────────\n\nDEFINE STEP endPending                                                    -- §7-4-2\n  phase: \"end\"\n  optional: false\n  text: \"skills that read \\\"at the end of the turn\\\" enter pending, except any [Auto] whose trigger condition was already fulfilled this turn (7-4-2)\"\n\nDEFINE STEP endRepeat                                                     -- §7-4-4\n  phase: \"end\"\n  optional: false\n  text: \"if an \\\"at the end of the turn\\\" [Auto] has still not been fulfilled this turn, the End Phase is carried out again from the beginning (7-4-4)\"\n\nDEFINE STEP endEffects                                                    -- §7-4-5\n  phase: \"end\"\n  optional: false\n  text: \"every effect that lasts \\\"for the turn\\\" or \\\"until the end of the turn\\\" ends, for the turn player and then for the non-turn player (7-4-5, 7-4-6)\"\n\nDEFINE STEP endTurn                                                       -- §7-4-7\n  phase: \"end\"\n  optional: false\n  text: \"the turn ends, the non-turn player becomes the turn player, and play proceeds to the next turn's Charge Phase (7-4-7)\"\n\n-- ── the game is over (§0-1-3) ─────────────────────────────────────────────\n\nDEFINE STEP gameEnd                                                       -- §0-1-3\n  phase: \"over\"\n  optional: false\n  prompt: \"gameOver\"\n  text: \"a player has fulfilled a defeat condition and the game has ended (0-1-3, 0-1-3-1)\"\n\n-- ── how the game ends (§0-1-3) ────────────────────────────────────────────\n--\n-- The two defeat conditions of 0-1-3-2. A player who fulfils either loses\n-- immediately (0-1-3-1), and a player whose opponent loses while they did not\n-- wins (0-1-3).\n--\n-- Two more ways the manual ends a game are not declared, because a condition\n-- in this language reads the board and neither of these is on it: conceding\n-- (0-1-3-4), which is a player's act and which no card may cause or replace\n-- (0-2-2-1), and a card that makes a player win or lose as its effect\n-- resolves (0-1-3-5). Nor can the draw of 0-1-3-3 be said, since \"both\n-- players fulfil a defeat condition simultaneously\" is a statement about the\n-- other declarations rather than about the board. All three are in the\n-- history entry of 12 Sep 2026.\n\nDEFINE WIN lifeOut                                                        -- §0-1-3-2\n  IF count(IN you.life) <= 0\n  result: lose\n  who: you\n  text: \"there are no cards in your Life Area (0-1-3-2)\"\n\nDEFINE WIN deckOut                                                        -- §0-1-3-2\n  IF count(IN you.deck) <= 0\n  result: lose\n  who: you\n  text: \"there are no cards in your Deck Area (0-1-3-2)\"\n",
  "keywords.rules": "-- Every keyword skill KEYWORD_NAMES (engine/script-schema.ts) lists, in that\n-- order. TAKES is the arity KeywordSkill (engine/types.ts) carries and\n-- keywordOf (engine/cards.ts) reads back; scripts/verify/rulesets.ts checks\n-- both against this file. text: is the glossary's meaning line, verbatim\n-- (src/lib/arena/glossary.ts), so /arena/rules/keywords can render it from\n-- here once Stage 8 (#159) swaps the reader. No HOOK bodies yet — that is\n-- Stage 7 (#153-#157); a keyword's own moments stay the engine's until then.\n\n-- 22-2\nDEFINE KEYWORD Awaken\n  TAKES (surge: boolean)\n  text: \"A Leader's own skill. Meet the printed condition, pay the cost, carry out the effect, then flip the Leader onto its awakened side. [Awaken: Surge] is the same skill under another name, and card text saying “[Awaken] skills” means both.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-25\nDEFINE KEYWORD Wish\n  TAKES ()\n  text: \"The same shape as [Awaken]: a condition, an effect, and then the Leader is flipped over.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-3\nDEFINE KEYWORD Field\n  TAKES ()\n  text: \"An Extra Card that stays on the table in Active Mode instead of going to the Drop Area. Its other skills work from there, and playing another [Field] Extra drops the one already out.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-4\nDEFINE KEYWORD Blocker\n  TAKES ()\n  text: \"When one of your other cards is attacked, switch this card to Rest Mode to become the guard card instead.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-6\nDEFINE KEYWORD Critical\n  TAKES ()\n  text: \"Life damage this card deals by attacking goes to the opponent's Drop Area instead of their hand.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-7\nDEFINE KEYWORD Strike\n  TAKES (x: number)\n  text: \"When this card would deal less than X life damage by attacking, it deals X instead — 2, 3 or 4.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-8\nDEFINE KEYWORD Attack\n  TAKES (x: number)\n  text: \"When this card attacks, it switches back to Active Mode at the end of the battle — X−1 times a turn.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-9\nDEFINE KEYWORD Revenge\n  TAKES ()\n  text: \"When this card becomes the guard card, KO the attacking card at the end of the battle.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-12\nDEFINE KEYWORD Indestructible\n  TAKES ()\n  text: \"This card can't be KO'd or moved out of your Battle Area by the opponent's skills or as a result of battle.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-16\nDEFINE KEYWORD Barrier\n  TAKES ()\n  text: \"This card can't be chosen by the skills of cards your opponent masters.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-20\nDEFINE KEYWORD Deflect\n  TAKES ()\n  text: \"This card isn't affected by your opponent's [Counter: Play] skills. Valid in every area.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-39\nDEFINE KEYWORD Unique\n  TAKES ()\n  text: \"While a card with [Unique] is in play you can't play another card with the same name. If two are somehow in play at once, their master keeps one and drops the rest.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-40\nDEFINE KEYWORD Servant\n  TAKES ()\n  text: \"+10000 power, and the card does not switch to Active Mode during its master's Charge Phase.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-31\nDEFINE KEYWORD \"Energy-Exhaust\"\n  TAKES ()\n  text: \"When this card is placed in an Energy Area, it arrives in Rest Mode. Valid in every area.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-18\nDEFINE KEYWORD \"Victory Strike\"\n  TAKES ()\n  text: \"Deal life damage by attacking with this card and you win the game.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-19\nDEFINE KEYWORD \"Warrior of Universe 7\"\n  TAKES ()\n  text: \"Treat your ≪Universe 7≫ cards in every area as having no specified cost — the coloured part of a play's price.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-14\nDEFINE KEYWORD Ultimate\n  TAKES ()\n  text: \"A deck may hold at most one card with [Ultimate], and a card with it that leaves play is removed from the game rather than going anywhere else.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-17\nDEFINE KEYWORD \"Super Combo\"\n  TAKES ()\n  text: \"A deck may hold at most four cards with [Super Combo], counted across all of them.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-28\nDEFINE KEYWORD \"Dragon Ball\"\n  TAKES ()\n  text: \"As many copies of a [Dragon Ball] card as you like, as long as no more than seven [Dragon Ball] cards are in the deck all told.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-24\nDEFINE KEYWORD Wormhole\n  TAKES ()\n  text: \"[Over Realm] and [Dark Over Realm] may be activated twice a turn between them instead of once.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-37\nDEFINE KEYWORD Invoker\n  TAKES ()\n  text: \"A Red/Blue multicolour Extra Card in your hand may be activated by switching one active Red/Blue multicolour energy to Rest Mode instead of paying its energy cost.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-35\nDEFINE KEYWORD Heroic\n  TAKES ()\n  text: \"When you play another card with [Heroic], draw 1 card; the skill is then negated on this card for the rest of the turn.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-36\nDEFINE KEYWORD Villainous\n  TAKES ()\n  text: \"When you play another card with [Villainous], your opponent chooses a card in their hand and drops it; the skill is then negated for the rest of the turn.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-33\nDEFINE KEYWORD Offering\n  TAKES ()\n  text: \"When this Battle Card is played, your opponent may put one of their life cards in their Drop Area. If they don't, you draw 2 cards.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-5\nDEFINE KEYWORD Evolve\n  TAKES (variant: string)\n  text: \"From hand: pay the cost, choose one of your Battle Cards matching the printed description, and play this card on top of it. [Xeno-Evolve] sends the chosen card to the Warp instead of stacking onto it.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-13\nDEFINE KEYWORD Union\n  TAKES (variant: string)\n  text: \"Three ways to play a Battle Card by naming characters. Fusion drops one of each named character from your hand, both of equal power. Potara plays this card on top of two named characters in your Battle Area. Absorb is activated from the Battle Area, and its text says which card is played onto this one.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-15, 22-23\nDEFINE KEYWORD \"Over Realm\"\n  TAKES (x: number, dark: boolean)\n  text: \"With X or more cards in your Drop Area — X or more black cards, for the dark one — send your whole Drop Area to the Warp as the cost and play this card from hand. The two share one activation a turn. A card played with [Over Realm] goes to the Warp at the end of that turn.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-22\nDEFINE KEYWORD Swap\n  TAKES (x: number)\n  text: \"Return this Battle Card to your hand and play a named Battle Card with an energy cost of X from your hand in its place.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-29\nDEFINE KEYWORD Arrival\n  TAKES (colors: colors)\n  text: \"During a battle, when the original colours of the Battle Cards in your Combo Area cover every colour named, pay the cost and play this card from hand.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-30\nDEFINE KEYWORD Aegis\n  TAKES (colors: colors)\n  text: \"In the Defense Step of your opponent's turn, drop cards from your hand covering the named colours to switch up to two of your energy from Rest to Active Mode.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-32\nDEFINE KEYWORD Alliance\n  TAKES (colors: colors)\n  text: \"When this card attacks, you may switch one or more of your other Battle Cards of the named colours to Rest Mode as the cost of the printed effect.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-34\nDEFINE KEYWORD Revive\n  TAKES (colors: colors)\n  text: \"When this Battle Card is KO'd, drop cards from hand whose original colours cover both named colours to play it back from your Drop Area. [Revive] is then negated on it for the turn.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-38\nDEFINE KEYWORD Successor\n  TAKES ()\n  text: \"Drop any number of mono-green, mono-yellow or Green/Yellow Battle Cards from your Battle Area whose energy costs add up to exactly this card's printed cost, and play it from hand.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-41\nDEFINE KEYWORD Overlord\n  TAKES ()\n  text: \"Put one of your Battle Cards with [Servant] at the bottom of your deck as the cost, and draw 1 card.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-42\nDEFINE KEYWORD Rejuvenate\n  TAKES ()\n  text: \"A Unison Card with cards beneath it: drop one of them and pay the skill cost, then add the top card of your deck to your life.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-43\nDEFINE KEYWORD \"Spirit Boost\"\n  TAKES (x: number)\n  text: \"Part of a skill's cost: remove X markers from your Unison Card. A skill whose [Spirit Boost] can't be paid can't be activated.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-45\nDEFINE KEYWORD Empower\n  TAKES (color: color, x: number)\n  text: \"When you play this Unison Card over one whose colour matches, you may move up to Y markers from the Unison being replaced onto this one. An [Empower] naming no colour takes them from a Unison of any colour.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-46\nDEFINE KEYWORD \"Z-Awaken\"\n  TAKES ()\n  text: \"From the Z-Deck, once a turn: pay the Z-Energy cost and the skill cost and place this Z-Leader on top of your already-awakened Leader, which has to match the printed description. The stack is one card from then on.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-47\nDEFINE KEYWORD \"Z-Stack\"\n  TAKES (x: number)\n  text: \"When this Z-Card is placed on your Leader or into a Battle or Unison Area, put up to X cards matching the printed description from your Z-Deck underneath it. They become part of the card on top.\"\n  -- Stage 7 (#153–#157)\n",
  "zones.rules": "-- The areas of the Dragon Ball Super Card Game, as declarations.\n--\n-- Every section cited is `docs/rules/rulemanual.txt`: §3 is the areas\n-- themselves, §1-10 card positions (Active and Rest Mode), §1-11 markers,\n-- §9-1-3-1 where a card's own skills are valid, §20-10 removal from the game\n-- and §23-2 cards placed under other cards.\n--\n-- The manual counts twelve areas (§3). Three more are declared below because\n-- a program has to be able to name them: `removed` (§20-10, where a card\n-- removed from the game is kept, which the manual pointedly says is no area\n-- at all), `under` (§23-2, the cards beneath another card) and `play`, which\n-- is the word for the three areas together in which a card is in play\n-- (§9-1-3-1). Each says so in its own text.\n--\n-- Two conventions, held to on every declaration so that a reader never has to\n-- ask what a missing line meant:\n--   `ordered: true`  the order of the cards is fixed by the rules and no\n--                    player may rearrange it (§3-2-2, §3-9-2). Every other\n--                    area lets its owner change the order freely, and is\n--                    written `ordered: false` rather than left out.\n--   `visibility`     who may read the faces: `none` is a secret area neither\n--                    player may check, `owner` a secret area its own player\n--                    may read, `all` an open area (§3-1-3).\n--\n-- Each player possesses one of every area, and two areas of the same name\n-- with different masters are different areas (§3-1-1) — which is what\n-- `owner: player` says. No area of this game is shared.\n\nDEFINE ZONE deck                                                          -- §3-2\n  owner: player\n  visibility: none\n  ordered: true\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  text: \"the deck, face down: neither player may check its contents or change its order (3-2-2)\"\n\nDEFINE ZONE hand                                                          -- §3-3\n  owner: player\n  visibility: owner\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  text: \"the cards a player holds: their own to read and reorder, and no limit on how many (3-3-2, 3-3-4)\"\n\nDEFINE ZONE drop                                                          -- §3-4\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  text: \"where KO'd Battle Cards, spent Unison Cards and activated Extra Cards are placed, face up (3-4-1, 3-4-3)\"\n\nDEFINE ZONE leader                                                        -- §3-5\n  owner: player\n  visibility: all\n  ordered: false\n  single: true\n  markers: false\n  inPlay: true\n  host: true\n  modes: [active, rest]\n  text: \"the one Leader Card, face up, which no effect or rule may move out of this area (3-5-1, 3-5-3)\"\n\nDEFINE ZONE battle                                                        -- §3-6\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: true\n  host: true\n  modes: [active, rest]\n  text: \"where Battle Cards and some Extra Cards are played, revealed and active, with no limit on how many (3-6-1, 3-6-3)\"\n\nDEFINE ZONE combo                                                         -- §3-7\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: true\n  text: \"the Battle Cards used in a combo, face up (3-7-1, 3-7-2)\"\n\nDEFINE ZONE energy                                                        -- §3-8\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: true\n  inPlay: false\n  host: false\n  modes: [active, rest]\n  text: \"the energy a player pays costs with, face up and active, and where energy markers are kept (3-8-1, 3-8-3, 1-14-3)\"\n\nDEFINE ZONE life                                                          -- §3-9\n  owner: player\n  visibility: none\n  ordered: true\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  text: \"the Leader's life, face down: its order may not be changed, but any card may be chosen when one leaves (3-9-2, 3-9-4)\"\n\nDEFINE ZONE warp                                                          -- §3-10\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  text: \"where cards sent to the Warp are placed, face up and readable by either player (3-10-2)\"\n\nDEFINE ZONE unison                                                        -- §3-11\n  owner: player\n  visibility: all\n  ordered: false\n  single: true\n  markers: true\n  inPlay: true\n  host: true\n  modes: [active, rest]\n  text: \"the one Unison Card, revealed and active, carrying the markers its skills are counted in (3-11-3, 3-11-4, 1-11-1)\"\n\nDEFINE ZONE zDeck                                                         -- §3-12\n  owner: player\n  visibility: owner\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  text: \"the Z-Deck, face down but its owner's to read and reorder; a face-up card in it is in an open area (3-12-2, 3-12-2-1)\"\n\nDEFINE ZONE zEnergy                                                       -- §3-13\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  text: \"the Z-Energy a player pays Z-Energy costs with, face up (3-13-2, 3-13-3)\"\n\nDEFINE ZONE removed                                                       -- §20-10\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  text: \"cards removed from the game: face up, visible to all, and in no area of the game at all (20-10-2, 20-10-3)\"\n\nDEFINE ZONE under                                                         -- §23-2\n  owner: player\n  visibility: all\n  ordered: true\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  text: \"the cards beneath another card, face up and skills negated; the area they count as being in is the area of the card on top (23-2-2, 23-2-2-2)\"\n\nDEFINE ZONE play                                                          -- §9-1-3-1\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: true\n  host: false\n  text: \"not a place a card is put: the word for the Leader, Battle and Unison Areas together, the areas a card's own skills are valid in (9-1-3-1)\"\n",
};
